import math

def shipping_cost(kg: float) -> float:
    """Flat $5.00 up to 1 kg, then $2.00 per additional started kg."""
    if kg <= 1:
        return 5.0
    # additional weight beyond the first kg
    extra = kg - 1
    # count each started kg as a whole number, ceil
    return 5.0 + 2.0 * math.ceil(extra)

