import csv

def fx_rate(date: str) -> float:
    """Return the USD->EUR closing rate on the given date, read from data/ecb_rates_2019.csv."""
    file_path = 'data/ecb_rates_2019.csv'
    try:
        with open(file_path, newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row.get('Date') == date:
                    return float(row.get('USD_EUR'))
    except FileNotFoundError:
        raise FileNotFoundError(f"{file_path} not found")
    raise KeyError(f"Rate for date {date} not found")

import re

def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    # Insert underscore between a lowercase/digit and an uppercase
    s = re.sub(r'(?<=[a-z0-9])([A-Z])', r'_\1', s)
    return s.lower()

